const encoder = new TextEncoder();
const COOKIE = "csa_admin_session";
async function syncGlobalAdminAuthorizations(env, triggerType="lifecycle", actorAdminId=null){const id=crypto.randomUUID(),started=now();try{const result=await syncGlobalAdminAuthorizationsRaw(env);await env.DB.prepare("INSERT INTO global_admin_sync_logs(id,trigger_type,outcome,synced_count,error_code,actor_admin_id,started_at,finished_at) VALUES(?,?,?, ?,NULL,?,?,?)").bind(id,triggerType,"success",Number(result.synced||0),actorAdminId,started,now()).run();return result}catch(e){const code=typeof e?.message==="string"&&/^global_authorization_sync_failed_(?:400|401|403|404|409|429|500|502|503)$/.test(e.message)?e.message:"internal_error";try{await env.DB.prepare("INSERT INTO global_admin_sync_logs(id,trigger_type,outcome,synced_count,error_code,actor_admin_id,started_at,finished_at) VALUES(?,?,?,0,?,?,?,?)").bind(id,triggerType,"failed",code,actorAdminId,started,now()).run()}catch(logError){console.error("Global sync log write failed","internal_error")}throw e}}
const ROLES = ["super_admin","project_admin","editor_admin","finance_admin","support_admin"];
const ROLE_PERMS = {
  super_admin: ["admins.read","admins.create","admins.update","admins.suspend","audit.read","projects.manage","content.manage","finance.read","support.manage"],
  project_admin: ["projects.manage","admins.read"],
  editor_admin: ["content.manage"],
  finance_admin: ["finance.read"],
  support_admin: ["support.manage"]
};
const json = (data, status=200, headers={}) => new Response(JSON.stringify(data), {status, headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff",...headers}});
const html = (body) => new Response(body,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","content-security-policy":"default-src 'self'; style-src 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'; form-action 'self';","x-content-type-options":"nosniff","referrer-policy":"no-referrer","x-frame-options":"DENY"}});
const b64 = (bytes) => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
const unb64 = (s) => Uint8Array.from(atob(s.replace(/-/g,"+").replace(/_/g,"/")),c=>c.charCodeAt(0));
const rand = (n=32) => crypto.getRandomValues(new Uint8Array(n));
const hex = (bytes) => [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,"0")).join("");
const sha = async (s) => hex(await crypto.subtle.digest("SHA-256",encoder.encode(s)));
const safeEq = (a,b) => { if(typeof a!=="string"||typeof b!=="string"||a.length!==b.length)return false; let x=0; for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i); return x===0; };
const pwHash = async (password,salt) => { const key=await crypto.subtle.importKey("raw",encoder.encode(password),"PBKDF2",false,["deriveBits"]); return b64(await crypto.subtle.deriveBits({name:"PBKDF2",salt:unb64(salt),iterations:100000,hash:"SHA-256"},key,256)); };
const otpHash = async (otp,id) => sha(`${id}:${otp}`);
async function accessIdentity(req,env){const token=req.headers.get('cf-access-jwt-assertion')||'';const p=token.split('.');if(p.length!==3||!env.ACCESS_TEAM_DOMAIN||!env.ACCESS_AUD)return false;try{const payload=JSON.parse(new TextDecoder().decode(unb64(p[1])));const issuer=env.ACCESS_TEAM_DOMAIN.replace(/\/$/,'');if(payload.iss!==issuer||!Array.isArray(payload.aud)||!payload.aud.includes(env.ACCESS_AUD)||!payload.exp||payload.exp<=Math.floor(Date.now()/1000)||String(payload.email||'').toLowerCase()!==String(env.ADMIN_EMAIL||'').toLowerCase())return false;const cr=await fetch(issuer+'/cdn-cgi/access/certs');if(!cr.ok)return false;const jwks=await cr.json();const h=JSON.parse(new TextDecoder().decode(unb64(p[0])));const jwk=(jwks.keys||[]).find(k=>k.kid===h.kid&&k.kty==='RSA');if(!jwk||h.alg!=='RS256')return false;const key=await crypto.subtle.importKey('jwk',jwk,{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']);return await crypto.subtle.verify('RSASSA-PKCS1-v1_5',key,unb64(p[2]),encoder.encode(p[0]+'.'+p[1]));}catch{return false;}}

const cookie = (req) => Object.fromEntries((req.headers.get("cookie")||"").split(";").map(x=>x.trim()).filter(Boolean).map(x=>{const i=x.indexOf("=");return [x.slice(0,i),x.slice(i+1)]}))[COOKIE];
const setCookie = (token,maxAge=43200) => `${COOKIE}=${token}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${maxAge}`;
const clearCookie = () => `${COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0`;
const now = () => new Date().toISOString();
const id = () => crypto.randomUUID();
const audit = (db,actor,action,target=null,meta={}) => db.prepare("INSERT INTO admin_audit_logs (id,actor_admin_id,action,target_admin_id,metadata_json,request_id) VALUES (?,?,?,?,?,?)").bind(id(),actor,action,target,JSON.stringify(meta),id()).run();
const mail = async (env,to,subject,content) => { const r=await fetch("https://api.resend.com/emails",{method:"POST",headers:{Authorization:`Bearer ${env.RESEND_API_KEY}`,"Content-Type":"application/json"},body:JSON.stringify({from:env.RESEND_FROM_EMAIL,to:[to],subject,html:content})}); if(!r.ok) throw new Error("email_delivery_failed"); };
const sendOtp = async (env,admin,purpose) => { const otp=String(crypto.getRandomValues(new Uint32Array(1))[0]%1000000).padStart(6,"0"), challenge=id(), expires=new Date(Date.now()+5*60000).toISOString(); await env.DB.prepare("INSERT INTO admin_otp_challenges (id,admin_id,otp_hash,purpose,expires_at) VALUES (?,?,?,?,?)").bind(challenge,admin.id,await otpHash(otp,challenge),purpose,expires).run(); await mail(env,admin.email,"CSA Admin verification code",`<div style="font-family:Arial,sans-serif;max-width:520px;margin:auto;padding:28px"><h2 style="color:#102a43">CSA Global Admin</h2><p>Your one-time verification code is:</p><div style="font-size:32px;letter-spacing:8px;font-weight:bold;padding:18px;background:#f1f5f9;border-radius:10px">${otp}</div><p>This code expires in 5 minutes. Do not share it with anyone.</p></div>`); return challenge; };
const body = async req => { try { return await req.json(); } catch { return {}; } };
const originOk = req => { const o=req.headers.get("origin"); return !o || o===new URL(req.url).origin; };
const employeeOriginOk = req => { const o=req.headers.get('origin'); return !o || o===new URL(req.url).origin || o==='https://employee.creatorsupportamravati.in'; };
async function current(req,env){ const raw=cookie(req); if(!raw)return null; const h=await sha(raw); const row=await env.DB.prepare("SELECT s.id AS session_id,s.expires_at,s.revoked_at,s.last_seen_at,s.created_at,a.id,a.user_id,a.email,a.display_name,a.role,a.status,a.must_change_password FROM admin_sessions s JOIN admin_accounts a ON a.id=s.admin_id WHERE s.session_token_hash=? LIMIT 1").bind(h).first(); if(!row||row.revoked_at||row.status!=="active"||new Date(row.expires_at)<=new Date())return null; const cutoff=new Date(Date.now()-30*60*1000).toISOString(); const expired=await env.DB.prepare("UPDATE admin_sessions SET revoked_at=? WHERE id=? AND revoked_at IS NULL AND COALESCE(last_seen_at,created_at)<=?").bind(now(),row.session_id,cutoff).run(); if((expired.meta?.changes||0)===1)return null; const touched=await env.DB.prepare("UPDATE admin_sessions SET last_seen_at=? WHERE id=? AND revoked_at IS NULL").bind(now(),row.session_id).run(); if((touched.meta?.changes||0)!==1)return null; return row; }
const can = (u,p) => !!u && (ROLE_PERMS[u.role]||[]).includes(p);
const portalRoleAllowed = (req,env,role) => { const host=new URL(req.url).hostname.toLowerCase(),staging=env?.ENVIRONMENT==="staging"; if(host==="superadmin-isolated-staging.creatorsupportamravati.in"||host==="superadmin-editor-staging.creatorsupportamravati.in"||host==="csa-superadmin-isolated-staging.creatorsupportamravati.workers.dev")return staging&&role==="super_admin"; if(host==="superadmin-staging.creatorsupportamravati.in")return staging&&role==="super_admin"; if(host==="admin-isolated-staging.creatorsupportamravati.in")return staging&&role!=="super_admin"; if(host==="admin-staging.creatorsupportamravati.in")return staging&&role!=="super_admin"; if(host==="superadmin.creatorsupportamravati.in")return role==="super_admin"; if(host==="admin.creatorsupportamravati.in")return role!=="super_admin"; return false; };
async function startLogin(req,env){ const b=await body(req); const uid=String(b.user_id||"").trim(); if(!uid||!b.password)return json({ok:false,error:"invalid_credentials"},401); const isMobile=/^\+?[0-9]{10,15}$/.test(uid); if(isMobile){const mobile=await env.DB.prepare("SELECT phone_verified,sms_login_enabled FROM admin_accounts WHERE phone_number=? LIMIT 1").bind(uid.startsWith("+")?uid:"+91"+uid).first(); if(mobile)return json({ok:false,error:"mobile_login_requires_verified_sms_setup"},503); } const ip=await sha(req.headers.get("cf-connecting-ip")||"unknown"); const recent=await env.DB.prepare("SELECT COUNT(*) AS n FROM admin_login_attempts WHERE (user_id=? OR ip_hash=?) AND datetime(attempted_at)>datetime('now','-15 minutes')").bind(uid,ip).first(); if((recent?.n||0)>=8)return json({ok:false,error:"too_many_attempts"},429); const a=await env.DB.prepare("SELECT * FROM admin_accounts WHERE user_id=? COLLATE NOCASE OR email=? COLLATE NOCASE LIMIT 1").bind(uid,uid).first(); let ok=false; if(a?.status==="active"&&a.password_hash&&portalRoleAllowed(req,env,a.role)){ const [salt,hash]=a.password_hash.split("."); ok=safeEq(await pwHash(String(b.password),salt),hash); }
 await env.DB.prepare("INSERT INTO admin_login_attempts (id,user_id,ip_hash,success) VALUES (?,?,?,?)").bind(id(),uid,ip,ok?1:0).run(); if(!ok){ if(a)await audit(env.DB,a.id,"login.failed",a.id); return json({ok:false,error:"invalid_credentials"},401); } try { const challenge=await sendOtp(env,a,"login"); return json({ok:true,step:"otp",challenge_id:challenge,masked_email:a.email.replace(/^(.).+(@.*)$/,"$1***$2")}); } catch { return json({ok:false,error:"otp_delivery_failed"},503); } }
async function verifyOtp(req,env){
 const b=await body(req);
 const c=await env.DB.prepare("SELECT * FROM admin_otp_challenges WHERE id=? AND purpose='login' AND consumed_at IS NULL").bind(String(b.challenge_id||"")).first();
 if(!c||new Date(c.expires_at)<=new Date()||c.attempts>=5)return json({ok:false,error:"invalid_or_expired_code"},400);
 const matches=safeEq(await otpHash(String(b.otp||""),c.id),c.otp_hash);
 if(!matches){await env.DB.prepare("UPDATE admin_otp_challenges SET attempts=attempts+1 WHERE id=? AND consumed_at IS NULL").bind(c.id).run();return json({ok:false,error:"invalid_or_expired_code"},400);}
 const a=await env.DB.prepare("SELECT * FROM admin_accounts WHERE id=? AND status='active'").bind(c.admin_id).first();
 if(!a||!portalRoleAllowed(req,env,a.role))return json({ok:false,error:"account_unavailable"},403);
 const claimAt=now();
 const claim=await env.DB.prepare("UPDATE admin_otp_challenges SET consumed_at=? WHERE id=? AND purpose='login' AND consumed_at IS NULL AND expires_at>? AND attempts<5 AND otp_hash=? AND admin_id=?").bind(claimAt,c.id,now(),c.otp_hash,a.id).run();
 if((claim.meta?.changes||0)!==1)return json({ok:false,error:"invalid_or_expired_code"},400);
 const token=b64(rand(32)), expires=new Date(Date.now()+12*3600000).toISOString();
 await env.DB.batch([
  env.DB.prepare("INSERT INTO admin_sessions (id,admin_id,session_token_hash,expires_at,ip_hash,user_agent) VALUES (?,?,?,?,?,?)").bind(id(),a.id,await sha(token),expires,await sha(req.headers.get("cf-connecting-ip")||"unknown"),(req.headers.get("user-agent")||"").slice(0,300)),
  env.DB.prepare("UPDATE admin_accounts SET last_login_at=?,updated_at=? WHERE id=? AND status='active'").bind(now(),now(),a.id)
 ]);
 await audit(env.DB,a.id,"login.success",a.id);
 return json({ok:true,user:{user_id:a.user_id,name:a.display_name,role:a.role,must_change_password:!!a.must_change_password}},200,{"set-cookie":setCookie(token)});
}
async function recoveryRequest(req,env){
 const b=await body(req),email=String(b.email||"").trim().toLowerCase();
 if(!/^\S+@\S+\.\S+$/.test(email))return json({ok:false,error:"enter_valid_registered_email"},400);
 const a=await env.DB.prepare("SELECT * FROM admin_accounts WHERE email=? COLLATE NOCASE AND status='active' LIMIT 1").bind(email).first();
 if(!a||!portalRoleAllowed(req,env,a.role))return json({ok:true});
 const recent=await env.DB.prepare("SELECT COUNT(*) AS n FROM admin_otp_challenges WHERE admin_id=? AND purpose='password_reset' AND created_at>datetime('now','-15 minutes')").bind(a.id).first();
 if((recent?.n||0)>=3)return json({ok:false,error:"recovery_rate_limited"},429);
 try{const challenge=await sendOtp(env,a,"password_reset");return json({ok:true,challenge_id:challenge});}catch(e){console.error("CSA recovery email failed","internal_error");return json({ok:false,error:"otp_delivery_failed"},503);}
}
async function recoveryVerify(req,env){
 const b=await body(req),mode=String(b.mode||"");
 if(!["identify","reset"].includes(mode))return json({ok:false,error:"invalid_recovery_action"},400);
 if(mode==="reset"&&String(b.password||"").length<12)return json({ok:false,error:"password_minimum_12_characters"},400);
 const c=await env.DB.prepare("SELECT * FROM admin_otp_challenges WHERE id=? AND purpose='password_reset' AND consumed_at IS NULL").bind(String(b.challenge_id||"")).first();
 if(!c||new Date(c.expires_at)<=new Date()||c.attempts>=5)return json({ok:false,error:"invalid_or_expired_code"},400);
 const matches=safeEq(await otpHash(String(b.otp||""),c.id),c.otp_hash);
 if(!matches){await env.DB.prepare("UPDATE admin_otp_challenges SET attempts=attempts+1 WHERE id=? AND consumed_at IS NULL").bind(c.id).run();return json({ok:false,error:"invalid_or_expired_code"},400);}
 const a=await env.DB.prepare("SELECT * FROM admin_accounts WHERE id=? AND status='active'").bind(c.admin_id).first();
 if(!a||!portalRoleAllowed(req,env,a.role))return json({ok:false,error:"account_unavailable"},403);
 if(mode==="identify"){
  const claim=await env.DB.prepare("UPDATE admin_otp_challenges SET consumed_at=? WHERE id=? AND purpose='password_reset' AND consumed_at IS NULL AND expires_at>? AND attempts<5 AND otp_hash=? AND admin_id=?").bind(now(),c.id,now(),c.otp_hash,a.id).run();
  if((claim.meta?.changes||0)!==1)return json({ok:false,error:"invalid_or_expired_code"},400);
  await audit(env.DB,a.id,"account.recovery.user_id",a.id);
  return json({ok:true,user_id:a.user_id});
 }
 const salt=b64(rand(16)),hash=salt+"."+await pwHash(String(b.password),salt);
 const claimAt=new Date().toISOString().replace(/\.(\d{3})Z$/,(_,ms)=>'.'+ms+Array.from(rand(4),v=>v.toString(16).padStart(2,'0')).join('')+'Z');
 const result=await env.DB.batch([
  env.DB.prepare("UPDATE admin_otp_challenges SET consumed_at=? WHERE id=? AND purpose='password_reset' AND consumed_at IS NULL AND expires_at>? AND attempts<5 AND otp_hash=? AND admin_id=?").bind(claimAt,c.id,now(),c.otp_hash,a.id),
  env.DB.prepare("UPDATE admin_accounts SET password_hash=?,updated_at=?,must_change_password=0 WHERE id=? AND status='active' AND EXISTS (SELECT 1 FROM admin_otp_challenges WHERE id=? AND admin_id=? AND purpose='password_reset' AND consumed_at=?)").bind(hash,now(),a.id,c.id,a.id,claimAt),
  env.DB.prepare("UPDATE admin_sessions SET revoked_at=? WHERE admin_id=? AND revoked_at IS NULL AND EXISTS (SELECT 1 FROM admin_otp_challenges WHERE id=? AND admin_id=? AND purpose='password_reset' AND consumed_at=?)").bind(now(),a.id,c.id,a.id,claimAt)
 ]);
 if((result[0]?.meta?.changes||0)!==1||(result[1]?.meta?.changes||0)!==1)return json({ok:false,error:"invalid_or_expired_code"},400);
 await audit(env.DB,a.id,"account.password_reset",a.id);
 return json({ok:true});
}
async function bootstrap(req,env){ if(!await accessIdentity(req,env))return json({ok:false,error:"access_authentication_required"},403); const b=await body(req); const count=await env.DB.prepare("SELECT COUNT(*) AS n FROM admin_accounts WHERE role='super_admin'").first(); if((count?.n||0)>0)return json({ok:false,error:"bootstrap_already_completed"},409); const email=String(b.email||"").trim().toLowerCase(); if(email!==String(env.ADMIN_EMAIL||"").trim().toLowerCase())return json({ok:false,error:"email_must_match_authorized_admin"},403); const user=String(b.user_id||"").trim(),name=String(b.display_name||"").trim(),password=String(b.password||""); if(!email||!user||!name||password.length<12||!/^\S+@\S+\.\S+$/.test(email))return json({ok:false,error:"provide_valid_details_password_min_12"},400); const aid=id(),salt=b64(rand(16)),hash=`${salt}.${await pwHash(password,salt)}`; try { await env.DB.prepare("INSERT INTO admin_accounts (id,user_id,email,display_name,role,password_hash,status,must_change_password) VALUES (?,?,?,?,? ,?,'active',0)").bind(aid,user,email,name,"super_admin",hash).run(); const a={id:aid,email}; try { const challenge=await sendOtp(env,a,"login"); return json({ok:true,step:"otp",challenge_id:challenge}); } catch(e){ await env.DB.prepare("DELETE FROM admin_accounts WHERE id=?").bind(aid).run(); return json({ok:false,error:"otp_delivery_failed"},503); } } catch { return json({ok:false,error:"account_already_exists_or_database_error"},409); } }
async function validateAdminInvite(env,b){
 const user=String(b.user_id||"").trim(),email=String(b.email||"").trim().toLowerCase(),name=String(b.display_name||"").trim(),role=String(b.role||"");
 if(!user||user.length<3||user.length>80||!/^[A-Za-z0-9._-]+$/.test(user)||!(/^\S+@\S+\.\S+$/.test(email))||email.length>254||!name||name.length>120||!ROLES.includes(role)||role==="super_admin")return {ok:false,status:400,error:"invalid_admin_details_or_role"};
 const [byUser,byEmail,financeModule]=await Promise.all([env.DB.prepare("SELECT id FROM admin_accounts WHERE user_id=? LIMIT 1").bind(user).first(),env.DB.prepare("SELECT id FROM admin_accounts WHERE email=? COLLATE NOCASE LIMIT 1").bind(email).first(),role==="finance_admin"?env.DB.prepare("SELECT module_key FROM csa_module_registry WHERE module_key='finance' LIMIT 1").first():Promise.resolve({module_key:"not_required"})]);
 const checks={user_id_available:!byUser,email_available:!byEmail,role_allowed:true,finance_module_ready:!!financeModule};
 return {ok:checks.user_id_available&&checks.email_available&&checks.finance_module_ready,status:checks.user_id_available&&checks.email_available&&checks.finance_module_ready?200:409,error:"invitation_preflight_blocked",checks,normalized:{user_id:user,email,display_name:name,role},default_finance_access:role==="finance_admin"?"read":null};
}
async function invitationPreflight(req,env,u){if(!can(u,"admins.create"))return json({ok:false,error:"forbidden"},403);const b=await body(req),v=await validateAdminInvite(env,b);return json({ok:true,ready:v.ok,checks:v.checks||{},normalized:v.normalized||null,default_finance_access:v.default_finance_access||null,message:v.ok?"preflight_passed":v.error},v.ok?200:(v.status||400));}
async function invite(req,env,u){
 if(!can(u,"admins.create"))return json({ok:false,error:"forbidden"},403);
 const b=await body(req),v=await validateAdminInvite(env,b);if(!v.ok)return json({ok:false,error:v.error||"invitation_preflight_blocked",checks:v.checks||{}},v.status||400);
 const user=v.normalized.user_id,email=v.normalized.email,name=v.normalized.display_name,role=v.normalized.role,aid=id(),token=b64(rand(32)),expires=new Date(Date.now()+24*3600000).toISOString();
 try{
  await env.DB.prepare("INSERT INTO admin_accounts (id,user_id,email,display_name,role,status,created_by) VALUES (?,?,?,?,?,'pending',?)").bind(aid,user,email,name,role,u.id).run();
  if(role==="finance_admin")await env.DB.prepare("INSERT INTO csa_admin_module_access (id,admin_id,module_key,access_level,granted_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?)").bind(id(),aid,"finance","read",u.id,now(),now()).run();
  await env.DB.prepare("INSERT INTO admin_enrollment_tokens (id,admin_id,token_hash,purpose,expires_at) VALUES (?,?,?,'admin_invitation',?)").bind(id(),aid,await sha(token),expires).run();
  const dashboardUrl=String(env.ADMIN_DASHBOARD_URL||"").trim();let dashboard;try{dashboard=new URL(dashboardUrl);}catch{throw new Error("admin_dashboard_url_invalid");}if(dashboard.protocol!=="https:"||dashboard.hostname!=="admin-isolated-staging.creatorsupportamravati.in")throw new Error("admin_dashboard_url_invalid");const link=dashboard.origin+"/?invite="+encodeURIComponent(token);
  await mail(env,email,"Your CSA Admin invitation","<div style=\"font-family:Arial,sans-serif\"><h2>CSA Global Admin invitation</h2><p>You have been invited as <b>"+role.replace(/_/g," ")+"</b>.</p><p><a href=\""+link+"\">Accept invitation and set password</a></p><p>This link expires in 24 hours.</p></div>");
  await audit(env.DB,u.id,"admin.invited",aid,{role});return json({ok:true,message:"invitation_sent"},201);
 }catch(e){try{await env.DB.batch([env.DB.prepare("DELETE FROM admin_enrollment_tokens WHERE admin_id=? AND purpose=?").bind(aid,"admin_invitation"),env.DB.prepare("DELETE FROM csa_admin_module_access WHERE admin_id=? AND module_key=?").bind(aid,"finance"),env.DB.prepare("DELETE FROM admin_accounts WHERE id=? AND status=?").bind(aid,"pending")]);}catch(cleanup){console.error("Invitation cleanup pending","internal_error");}console.error("Admin invitation failed","internal_error");return json({ok:false,error:"invitation_failed_check_email_or_duplicate"},409);}
}
async function updateFinanceAccess(req,env,u,aid){
 if(u.role!=="super_admin")return json({ok:false,error:"forbidden"},403);
 const b=await body(req),level=String(b.access_level||"");if(!["none","read","write","manage"].includes(level))return json({ok:false,error:"invalid_finance_access_level"},400);
 const result=await env.DB.prepare("INSERT INTO csa_admin_module_access (id,admin_id,module_key,access_level,granted_by,created_at,updated_at) SELECT ?,id,'finance',?,?,?,? FROM admin_accounts WHERE id=? AND role='finance_admin' ON CONFLICT(admin_id,module_key) DO UPDATE SET access_level=excluded.access_level,granted_by=excluded.granted_by,updated_at=excluded.updated_at").bind(id(),level,u.id,now(),now(),aid).run();
 if(!(result.meta?.changes||0))return json({ok:false,error:"finance_admin_not_found"},404);
 await audit(env.DB,u.id,"admin.finance_access_updated",aid,{access_level:level});
 try{const sync=await syncGlobalAdminAuthorizations(env,"finance_access_updated",u.id);return json({ok:true,admin_id:aid,finance_access_level:level,global_authorizations_synced:sync.synced});}catch(e){console.error("Finance access sync pending","internal_error");return json({ok:true,admin_id:aid,finance_access_level:level,global_sync:"pending_retry_required"},202);}
}
async function acceptInvite(req,env){ if(!portalRoleAllowed(req,env,"project_admin"))return json({ok:false,error:"not_found"},404); const b=await body(req),token=String(b.token||""),password=String(b.password||""); if(password.length<12)return json({ok:false,error:"password_minimum_12_characters"},400); const tokenHash=await sha(token); const t=await env.DB.prepare("SELECT * FROM admin_enrollment_tokens WHERE token_hash=? AND purpose='admin_invitation' AND consumed_at IS NULL").bind(tokenHash).first(); if(!t||new Date(t.expires_at)<=new Date())return json({ok:false,error:"invitation_invalid_or_expired"},400); const salt=b64(rand(16)),hash=salt+"."+await pwHash(password,salt); const stamp=now(),claim=stamp+":"+id(); const results=await env.DB.batch([env.DB.prepare("UPDATE admin_enrollment_tokens SET consumed_at=? WHERE id=? AND token_hash=? AND purpose='admin_invitation' AND consumed_at IS NULL AND expires_at>?").bind(claim,t.id,tokenHash,stamp),env.DB.prepare("UPDATE admin_accounts SET password_hash=?,status='active',must_change_password=0,updated_at=? WHERE id=? AND (status='pending' OR (status='active' AND password_hash IS NULL)) AND EXISTS (SELECT 1 FROM admin_enrollment_tokens WHERE id=? AND token_hash=? AND purpose='admin_invitation' AND consumed_at=?)").bind(hash,stamp,t.admin_id,t.id,tokenHash,claim),env.DB.prepare("UPDATE admin_enrollment_tokens SET consumed_at=NULL WHERE id=? AND token_hash=? AND purpose='admin_invitation' AND consumed_at=? AND NOT EXISTS (SELECT 1 FROM admin_accounts WHERE id=? AND password_hash=? AND status='active')").bind(t.id,tokenHash,claim,t.admin_id,hash)]); const claimed=results?.[0]?.meta?.changes||0,activated=results?.[1]?.meta?.changes||0; if(claimed!==1)return json({ok:false,error:"invitation_invalid_or_already_used"},409); if(activated!==1)return json({ok:false,error:"invitation_account_activation_failed_retry"},409); await audit(env.DB,t.admin_id,"admin.invitation_accepted",t.admin_id); try { const sync=await syncGlobalAdminAuthorizations(env); return json({ok:true,message:"account_activated_login_now",global_authorizations_synced:sync.synced}); } catch(e) { console.error("Global authorization sync pending","internal_error"); return json({ok:true,message:"account_activated_login_now",global_sync:"pending_retry_required"},202); } }
async function listAdmins(env,u){ if(!can(u,"admins.read"))return json({ok:false,error:"forbidden"},403); const rows=await env.DB.prepare("SELECT a.id,a.user_id,a.email,a.display_name,a.role,a.status,a.must_change_password,a.created_at,a.last_login_at,COALESCE((SELECT m.access_level FROM csa_admin_module_access m WHERE m.admin_id=a.id AND m.module_key='finance'),'none') AS finance_access_level FROM admin_accounts a ORDER BY a.created_at DESC").all(); return json({ok:true,admins:rows.results||[]}); }
async function updateAdmin(req,env,u,aid){ if(!can(u,"admins.update"))return json({ok:false,error:"forbidden"},403); const b=await body(req), role=b.role, status=b.status; const a=await env.DB.prepare("SELECT id,role,status FROM admin_accounts WHERE id=?").bind(aid).first(); if(!a||a.role==="super_admin"||role==="super_admin")return json({ok:false,error:"admin_not_found_or_protected"},404); if(role&&!ROLES.includes(role))return json({ok:false,error:"invalid_role"},400); if(status&&!['active','suspended','deactivated'].includes(status))return json({ok:false,error:"invalid_status"},400); await env.DB.prepare("UPDATE admin_accounts SET role=COALESCE(?,role),status=COALESCE(?,status),updated_at=? WHERE id=?").bind(role||null,status||null,now(),aid).run(); if(role==='finance_admin'){await env.DB.prepare('INSERT INTO csa_admin_module_access (id,admin_id,module_key,access_level,granted_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT(admin_id,module_key) DO UPDATE SET access_level=CASE WHEN csa_admin_module_access.access_level IN (?,?) THEN csa_admin_module_access.access_level ELSE ? END,granted_by=excluded.granted_by,updated_at=excluded.updated_at').bind(id(),aid,'finance','read',u.id,now(),now(),'write','manage','read').run();}else if(role&&a.role==='finance_admin'){await env.DB.prepare('UPDATE csa_admin_module_access SET access_level=?,granted_by=?,updated_at=? WHERE admin_id=? AND module_key=?').bind('none',u.id,now(),aid,'finance').run();} if((role&&role!==a.role)||(status&&status!=="active"))await env.DB.prepare("UPDATE admin_sessions SET revoked_at=? WHERE admin_id=? AND revoked_at IS NULL").bind(now(),aid).run(); await audit(env.DB,u.id,"admin.updated",aid,{role:role||a.role,status:status||a.status}); try { const sync=await syncGlobalAdminAuthorizations(env); return json({ok:true,global_authorizations_synced:sync.synced}); } catch(e) { console.error("Global authorization sync pending","internal_error"); return json({ok:true,global_sync:"pending_retry_required"},202); } }
async function auditList(env,u){ if(!can(u,"audit.read"))return json({ok:false,error:"forbidden"},403); const r=await env.DB.prepare("SELECT l.id,l.action,l.metadata_json,l.created_at,a.user_id AS actor_user_id,t.user_id AS target_user_id FROM admin_audit_logs l LEFT JOIN admin_accounts a ON a.id=l.actor_admin_id LEFT JOIN admin_accounts t ON t.id=l.target_admin_id ORDER BY l.created_at DESC LIMIT 100").all(); return json({ok:true,logs:r.results||[]}); }

