async function hasModuleAccess(env,u,moduleKey,required="read"){if(!u)return false;if(u.role==="super_admin")return true;const row=await env.DB.prepare("SELECT access_level FROM csa_admin_module_access WHERE admin_id=? AND module_key=?").bind(u.id,moduleKey).first();const rank={none:0,read:1,write:2,manage:3};return (rank[row?.access_level]??0)>=(rank[required]??1);}

