async function listFinance(env,u){const [i,e,s,p]=await Promise.all([env.DB.prepare("SELECT i.*,c.name AS client_name,c.company AS client_company,c.email AS client_email,c.phone AS client_phone,pr.title AS project_title,COALESCE((SELECT SUM(x.amount_paise) FROM csa_payments x WHERE x.invoice_id=i.id),0) AS paid_paise FROM csa_invoices i LEFT JOIN csa_clients c ON c.id=i.client_id LEFT JOIN csa_projects pr ON pr.id=i.project_id ORDER BY i.created_at DESC LIMIT 300").all(),env.DB.prepare("SELECT * FROM csa_expenses ORDER BY expense_date DESC LIMIT 300").all(),env.DB.prepare("SELECT COALESCE((SELECT SUM(amount_paise) FROM csa_payments WHERE paid_at>=date('now','start of month')),0) AS collected,COALESCE((SELECT SUM(amount_paise) FROM csa_expenses WHERE expense_date>=date('now','start of month')),0) AS expenses,COALESCE((SELECT SUM(i.amount_paise+i.tax_paise-COALESCE((SELECT SUM(x.amount_paise) FROM csa_payments x WHERE x.invoice_id=i.id),0)) FROM csa_invoices i WHERE i.status NOT IN ('paid','cancelled')),0) AS receivables").first(),env.DB.prepare("SELECT p.id,p.invoice_id,p.amount_paise,p.method,p.reference,p.paid_at,i.invoice_no,i.amount_paise AS invoice_amount_paise,i.tax_paise,i.issue_date,i.due_date,c.name AS client_name,c.company AS client_company,c.email AS client_email,c.phone AS client_phone FROM csa_payments p JOIN csa_invoices i ON i.id=p.invoice_id LEFT JOIN csa_clients c ON c.id=i.client_id ORDER BY p.paid_at DESC LIMIT 300").all()]);return json({ok:true,invoices:i.results||[],expenses:e.results||[],summary:s||{},payments:p.results||[]})}
async function createInvoice(req,env,u){const b=await body(req),a=Math.round(Number(b.amount)*100),t=Math.round(Number(b.tax||0)*100),client=String(b.client_id||'');if(!client||!Number.isFinite(a)||a<=0||!Number.isFinite(t)||t<0)return json({ok:false,error:'valid_client_and_amount_required'},400);const idv=id(),no='CSA-INV-'+Date.now();try{await env.DB.prepare("INSERT INTO csa_invoices (id,invoice_no,client_id,project_id,amount_paise,tax_paise,status,issue_date,due_date,notes,created_by) VALUES (?,?,?,?,?,?,'sent',?,?,?,?)").bind(idv,no,client,String(b.project_id||'')||null,a,t,String(b.issue_date||new Date().toISOString().slice(0,10)),String(b.due_date||'')||null,String(b.notes||''),u.id).run();return json({ok:true,invoice_no:no},201)}catch{return json({ok:false,error:'invoice_create_failed_check_client_or_project'},400)}}
async function createPayment(req,env,u){const b=await body(req),iid=String(b.invoice_id||''),a=Math.round(Number(b.amount)*100);if(!iid||!Number.isFinite(a)||a<=0)return json({ok:false,error:'valid_invoice_and_amount_required'},400);const i=await env.DB.prepare("SELECT * FROM csa_invoices WHERE id=? AND status!='cancelled'").bind(iid).first();if(!i)return json({ok:false,error:'invoice_not_found'},404);const p=await env.DB.prepare("SELECT COALESCE(SUM(amount_paise),0) AS total FROM csa_payments WHERE invoice_id=?").bind(iid).first(),bal=Number(i.amount_paise)+Number(i.tax_paise)-Number(p.total||0);if(a>bal)return json({ok:false,error:'payment_exceeds_balance'},400);await env.DB.prepare("INSERT INTO csa_payments (id,invoice_id,amount_paise,method,reference,recorded_by) VALUES (?,?,?,?,?,?)").bind(id(),iid,a,String(b.method||'')||null,String(b.reference||'')||null,u.id).run();const status=Number(p.total||0)+a>=Number(i.amount_paise)+Number(i.tax_paise)?'paid':'partially_paid';await env.DB.prepare("UPDATE csa_invoices SET status=? WHERE id=?").bind(status,iid).run();return json({ok:true,status},201)}
async function createExpense(req,env,u){const b=await body(req),a=Math.round(Number(b.amount)*100),cat=String(b.category||'').trim(),dt=String(b.expense_date||new Date().toISOString().slice(0,10));if(!cat||!Number.isFinite(a)||a<=0||!/^\\d{4}-\\d{2}-\\d{2}$/.test(dt))return json({ok:false,error:'valid_category_amount_and_date_required'},400);await env.DB.prepare("INSERT INTO csa_expenses (id,category,description,amount_paise,expense_date,vendor,reference,recorded_by) VALUES (?,?,?,?,?,?,?,?)").bind(id(),cat,String(b.description||'')||null,a,dt,String(b.vendor||'')||null,String(b.reference||'')||null,u.id).run();return json({ok:true},201)}
async function analytics(env,u){

 const q=async(sql)=>{const r=await env.DB.prepare(sql).first();return r||{}};
 const [clients,projects,tasks,admins,finance,monthly,workload]=await Promise.all([
 q("SELECT COUNT(*) AS total,SUM(CASE WHEN status='active' THEN 1 ELSE 0 END) AS active,SUM(CASE WHEN status='lead' THEN 1 ELSE 0 END) AS leads FROM csa_clients"),
 q("SELECT COUNT(*) AS total,SUM(CASE WHEN status='in_progress' THEN 1 ELSE 0 END) AS in_progress,SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) AS completed,SUM(CASE WHEN status='on_hold' THEN 1 ELSE 0 END) AS on_hold FROM csa_projects"),
 q("SELECT COUNT(*) AS total,SUM(CASE WHEN status='todo' THEN 1 ELSE 0 END) AS todo,SUM(CASE WHEN status='in_progress' THEN 1 ELSE 0 END) AS in_progress,SUM(CASE WHEN status='review' THEN 1 ELSE 0 END) AS review,SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) AS completed,SUM(CASE WHEN due_at IS NOT NULL AND due_at<datetime('now') AND status NOT IN ('completed','cancelled') THEN 1 ELSE 0 END) AS overdue FROM csa_tasks"),
 q("SELECT COUNT(*) AS total,SUM(CASE WHEN status='active' THEN 1 ELSE 0 END) AS active,SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending FROM admin_accounts"),
 q("SELECT COALESCE((SELECT SUM(amount_paise) FROM csa_payments WHERE paid_at>=date('now','start of month')),0) AS collected_month_paise,COALESCE((SELECT SUM(amount_paise) FROM csa_expenses WHERE expense_date>=date('now','start of month')),0) AS expenses_month_paise,COALESCE((SELECT SUM(i.amount_paise+i.tax_paise-COALESCE((SELECT SUM(p.amount_paise) FROM csa_payments p WHERE p.invoice_id=i.id),0)) FROM csa_invoices i WHERE i.status NOT IN ('paid','cancelled')),0) AS receivables_paise"),
 env.DB.prepare("SELECT strftime('%Y-%m',paid_at) AS month, SUM(amount_paise) AS amount_paise FROM csa_payments WHERE paid_at>=date('now','-5 months','start of month') GROUP BY strftime('%Y-%m',paid_at) ORDER BY month").all(),
 env.DB.prepare("SELECT a.user_id,a.display_name,COUNT(t.id) AS open_tasks,SUM(CASE WHEN t.due_at IS NOT NULL AND t.due_at<datetime('now') AND t.status NOT IN ('completed','cancelled') THEN 1 ELSE 0 END) AS overdue_tasks FROM admin_accounts a LEFT JOIN csa_tasks t ON t.assigned_to=a.id AND t.status NOT IN ('completed','cancelled') WHERE a.status='active' GROUP BY a.id ORDER BY open_tasks DESC LIMIT 8").all()
 ]);
 return json({ok:true,as_of:now(),clients,projects,tasks,admins,finance,monthly_revenue:monthly.results||[],team_workload:workload.results||[]});
}

