 if(!out&&(existing?.check_in_at||await env.DB.prepare("SELECT id FROM csa_attendance_punches WHERE employee_id=? AND work_date=? AND punch_type='check_in' AND review_status='pending' LIMIT 1").bind(e.id,date).first()))return json({ok:false,error:'already_checked_in_or_pending_review'},409);
 if(out&&(!existing?.check_in_at||existing?.check_out_at))return json({ok:false,error:existing?.check_out_at?'already_checked_out':'check_in_must_be_approved_first'},409);
 if(out&&await env.DB.prepare("SELECT id FROM csa_attendance_punches WHERE employee_id=? AND work_date=? AND punch_type='check_out' AND review_status='pending' LIMIT 1").bind(e.id,date).first())return json({ok:false,error:'check_out_already_pending_review'},409);
