async function empAttendanceTest(req,env){const e=await employeeCurrent(req,env);if(!e)return json({ok:false,error:'unauthorized'},401);const b=await body(req),mode=String(b.work_mode||''),lat=Number(b.latitude),lng=Number(b.longitude),accuracy=Number(b.accuracy_m),data=String(b.selfie_data||'');if(!['office','field'].includes(mode))return json({ok:false,error:'select_office_or_field_work'},400);if(!Number.isFinite(lat)||lat < -90||lat>90)return json({ok:false,error:'gps_latitude_missing_or_invalid'},400);if(!Number.isFinite(lng)||lng < -180||lng>180)return json({ok:false,error:'gps_longitude_missing_or_invalid'},400);if(!Number.isFinite(accuracy)||accuracy<=0||accuracy>10000)return json({ok:false,error:'gps_accuracy_missing_or_invalid',accuracy_received:Number.isFinite(accuracy)?accuracy:null},400);if(!data.startsWith('data:image/jpeg;base64,')||data.length>600000)return json({ok:false,error:'valid_selfie_required_max_400kb'},400);let binary;try{binary=atob(data.slice(23))}catch{return json({ok:false,error:'invalid_selfie_image'},400)}if(binary.length<3000||binary.length>420000||binary.charCodeAt(0)!==255||binary.charCodeAt(1)!==216||binary.charCodeAt(2)!==255)return json({ok:false,error:'selfie_must_be_a_valid_jpeg_under_400kb'},400);const distance=csaDistanceMeters(lat,lng,CSA_OFFICE.lat,CSA_OFFICE.lng);return json({ok:true,test_only:true,attendance_saved:false,selfie_saved:false,selfie_valid:true,accuracy_m:Math.round(accuracy),distance_m:Math.round(distance),within_office_geofence:distance<=CSA_OFFICE.radius,office_radius_m:CSA_OFFICE.radius,work_mode:mode,admin_review_required:true,message:'Safe test completed. No attendance or selfie was stored.'});}

