async function empWorkUpdates(req,env){const e=await employeeCurrent(req,env);if(!e)return json({ok:false,error:"unauthorized"},401);if(req.method==="GET"){const r=await env.DB.prepare("SELECT id,title,update_text,status,minutes_spent,review_status,review_note,created_at FROM csa_employee_work_updates WHERE employee_id=? ORDER BY created_at DESC LIMIT 50").bind(e.id).all(),u=r.results||[];for(const x of u){const m=await env.DB.prepare("SELECT id,file_name,media_type,file_size FROM csa_employee_work_media WHERE update_id=? ORDER BY created_at").bind(x.id).all();x.media=m.results||[];}return json({ok:true,updates:u});}if(req.method!=="POST")return json({ok:false,error:"method_not_allowed"},405);let f;try{f=await req.formData()}catch{return json({ok:false,error:"invalid_multipart_form"},400)}const title=String(f.get("title")||"").trim(),note=String(f.get("update_text")||"").trim(),status=String(f.get("status")||"in_progress"),mins=Number(f.get("minutes_spent")||0);if(!title||title.length>120||!note||note.length>3000||!["pending","in_progress","completed","blocked"].includes(status)||!Number.isInteger(mins)||mins<0||mins>1440)return json({ok:false,error:"valid_title_update_status_and_time_required"},400);const limits={"image/jpeg":8*1048576,"image/png":8*1048576,"image/webp":8*1048576,"video/mp4":20*1048576,"video/webm":20*1048576,"video/quicktime":20*1048576},up=f.getAll("files").filter(x=>x&&typeof x.arrayBuffer==="function"&&x.size>0);if(up.length>5)return json({ok:false,error:"maximum_5_attachments_allowed"},400);let total=0;for(const x of up){if(!limits[x.type])return json({ok:false,error:"unsupported_media_type"},400);if(x.size>limits[x.type])return json({ok:false,error:"attachment_size_limit_exceeded"},400);total+=x.size;}if(total>40*1048576)return json({ok:false,error:"total_upload_limit_40mb"},400);const uid=id(),keys=[];try{await env.DB.prepare("INSERT INTO csa_employee_work_updates(id,employee_id,title,update_text,status,minutes_spent) VALUES(?,?,?,?,?,?)").bind(uid,e.id,title,note,status,mins).run();for(const x of up){const mid=id(),ext=({"image/jpeg":"jpg","image/png":"png","image/webp":"webp","video/mp4":"mp4","video/webm":"webm","video/quicktime":"mov"})[x.type],key="work-updates/"+e.id+"/"+uid+"/"+mid+"."+ext;await env.ATTENDANCE_MEDIA.put(key,await x.arrayBuffer(),{httpMetadata:{contentType:x.type,cacheControl:"private, no-store"}});keys.push(key);await env.DB.prepare("INSERT INTO csa_employee_work_media(id,update_id,employee_id,object_key,media_type,file_name,file_size) VALUES(?,?,?,?,?,?,?)").bind(mid,uid,e.id,key,x.type,String(x.name||("upload."+ext)).replace(/[^a-zA-Z0-9._() -]/g,"_").slice(0,120),x.size).run();}return json({ok:true,id:uid},201);}catch(err){for(const k of keys){try{await env.ATTENDANCE_MEDIA.delete(k)}catch{}}try{await env.DB.prepare("DELETE FROM csa_employee_work_updates WHERE id=?").bind(uid).run()}catch{}console.error("work update upload failed","internal_error");return json({ok:false,error:"work_update_upload_failed"},500);}}
async function empWorkMedia(env,e,uid,mid){const m=await env.DB.prepare("SELECT m.object_key,m.media_type,m.file_name FROM csa_employee_work_media m JOIN csa_employee_work_updates u ON u.id=m.update_id WHERE m.id=? AND m.update_id=? AND u.employee_id=?").bind(mid,uid,e.id).first();if(!m)return json({ok:false,error:"work_media_not_found"},404);const o=await env.ATTENDANCE_MEDIA.get(m.object_key);return o?workMediaResponse(o,m.media_type,m.file_name):json({ok:false,error:"work_media_missing"},404);}
async function hrWorkUpdates(env,url){const st=String(url.searchParams.get("status")||"pending");if(!["pending","approved","changes_requested","all"].includes(st))return json({ok:false,error:"invalid_status"},400);const wh=st==="all"?"":"WHERE u.review_status=?",q="SELECT u.id,u.title,u.update_text,u.status,u.minutes_spent,u.review_status,u.review_note,u.created_at,e.employee_code,e.full_name,d.name AS department_name FROM csa_employee_work_updates u JOIN csa_employees e ON e.id=u.employee_id LEFT JOIN csa_departments d ON d.id=e.department_id "+wh+" ORDER BY u.created_at DESC LIMIT 300",r=st==="all"?await env.DB.prepare(q).all():await env.DB.prepare(q).bind(st).all(),u=r.results||[];for(const x of u){const m=await env.DB.prepare("SELECT id,file_name,media_type,file_size FROM csa_employee_work_media WHERE update_id=? ORDER BY created_at").bind(x.id).all();x.media=m.results||[];}return json({ok:true,updates:u});}
async function hrWorkMedia(env,uid,mid){const m=await env.DB.prepare("SELECT object_key,media_type,file_name FROM csa_employee_work_media WHERE id=? AND update_id=?").bind(mid,uid).first();if(!m)return json({ok:false,error:"work_media_not_found"},404);const o=await env.ATTENDANCE_MEDIA.get(m.object_key);return o?workMediaResponse(o,m.media_type,m.file_name):json({ok:false,error:"work_media_missing"},404);}
async function hrReviewWorkUpdate(req,env,u,uid){const b=await body(req),st=String(b.status||""),note=String(b.review_note||"").trim().slice(0,1000);if(!["approved","changes_requested"].includes(st))return json({ok:false,error:"invalid_review_status"},400);const old=await env.DB.prepare("SELECT employee_id,review_status FROM csa_employee_work_updates WHERE id=?").bind(uid).first();if(!old)return json({ok:false,error:"work_update_not_found"},404);if(old.review_status!=="pending")return json({ok:false,error:"pending_work_update_not_found"},409);const saved=await env.DB.prepare("UPDATE csa_employee_work_updates SET review_status=?,review_note=?,reviewed_by=?,reviewed_at=?,updated_at=? WHERE id=? AND review_status='pending'").bind(st,note||null,u.id,now(),now(),uid).run();if(!saved.meta?.changes)return json({ok:false,error:"work_update_review_conflict"},409);await audit(env.DB,u.id,"hr.work_update.reviewed",uid,{employee_id:old.employee_id,status:st});return json({ok:true});}

