async function empApplyLeave(req,env){const e=await employeeCurrent(req,env);if(!e)return json({ok:false,error:"unauthorized"},401);const b=await body(req),s=String(b.start_date||""),en=String(b.end_date||""),ty=String(b.leave_type||"casual"),reason=String(b.reason||"").trim();if(!["casual","sick","earned","unpaid","other"].includes(ty)||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(s)||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(en)||en<s||!reason)return json({ok:false,error:"valid_leave_details_required"},400);await env.DB.prepare("INSERT INTO csa_leave_requests(id,employee_id,leave_type,start_date,end_date,reason,status) VALUES(?,?,?,?,?,?,'pending')").bind(id(),e.id,ty,s,en,reason.slice(0,1000)).run();return json({ok:true});}
async function empPassword(req,env){const e=await employeeCurrent(req,env);if(!e)return json({ok:false,error:"unauthorized"},401);const b=await body(req),old=String(b.current_password||""),pw=String(b.new_password||"");if(pw.length<12)return json({ok:false,error:"password_minimum_12_characters"},400);const a=await env.DB.prepare("SELECT password_hash FROM csa_employee_auth WHERE employee_id=?").bind(e.id).first(),z=a.password_hash.split(".");if(z.length!==2||!safeEq(await pwHash(old,z[0]),z[1]))return json({ok:false,error:"current_password_incorrect"},400);const salt=b64(rand(16));await env.DB.prepare("UPDATE csa_employee_auth SET password_hash=?,must_change_password=0,updated_at=? WHERE employee_id=?").bind(salt+"."+await pwHash(pw,salt),now(),e.id).run();return json({ok:true});}
