  if(p==="/pricing-policy"&&req.method==="GET"){if(!adminOnly(u))return new Response("Forbidden",{status:403,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"}});return new Response("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CSA Super Admin · Pricing Policy</title><style>body{font:15px system-ui;background:#f3f6fb;color:#15243a;margin:0;padding:24px}.wrap{max-width:960px;margin:auto}.card{background:#fff;border:1px solid #e4eaf2;border-radius:16px;padding:22px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}input{width:100%;box-sizing:border-box;padding:11px;border:1px solid #ccd6e2;border-radius:8px;margin:6px 0 12px}button,a{background:#087f8c;color:white;border:0;padding:11px 15px;border-radius:8px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #e8edf3}.muted{color:#64748b}.msg{margin:12px 0} @media(max-width:600px){body{padding:12px}.card{padding:15px}table{display:block;overflow:auto}}</style></head><body><main class=\"wrap\"><a href=\"/\">← Back to Super Admin</a><h1>CSA Pricing Policy</h1><p class=\"muted\">Country-wise pricing margin, minimum margin and client advance rules. Changes are signed, audited and restricted to Super Admin.</p><div id=\"msg\" class=\"msg\"></div><section class=\"card\"><h2>Set / Update Country Pricing</h2><form id=\"form\"><div class=\"grid\"><label>Currency (ISO 4217)<input id=\"currency\" maxlength=\"3\" required placeholder=\"INR\"></label><label>CSA margin (%)<input id=\"margin\" type=\"number\" min=\"0\" max=\"100\" step=\"0.01\" required placeholder=\"15\"></label><label>Minimum margin (minor units)<input id=\"minimum\" type=\"number\" min=\"0\" step=\"1\" value=\"0\" required></label><label>Client advance (%)<input id=\"advance\" type=\"number\" min=\"1\" max=\"100\" step=\"0.01\" placeholder=\"50\"></label></div><button type=\"submit\">Save Pricing Policy</button></form><p class=\"muted\">Margin and advance are stored in basis points. Minimum margin is stored in the currency's minor unit (e.g. paise for INR).</p></section><section class=\"card\"><h2>Configured Policies</h2><div id=\"policies\">Loading…</div></section><section class=\"card\"><h2>Recent Pricing Audit</h2><div id=\"history\">Loading…</div></section></main><script>const $=id=>document.getElementById(id);function msg(t,ok=false){$('msg').textContent=t;$('msg').style.color=ok?'#087f5b':'#b42318'}async function api(method,body){const r=await fetch('/api/pricing-policy',{method,headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw Error(d.error||'Request failed');return d}function esc(s){return String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))}async function load(){try{const d=await api('GET');$('policies').innerHTML=d.policies.length?'<table><tr><th>Currency</th><th>Margin</th><th>Minimum</th><th>Advance</th><th>Status</th></tr>'+d.policies.map(x=>'<tr><td>'+esc(x.currency)+'</td><td>'+(x.margin_bps/100).toFixed(2)+'%</td><td>'+x.minimum_margin_minor+'</td><td>'+(x.client_advance_bps===null?'—':(x.client_advance_bps/100).toFixed(2)+'%')+'</td><td>'+esc(x.status)+'</td></tr>').join('')+'</table>':'No country pricing configured yet.';$('history').innerHTML=d.history.length?'<table><tr><th>Time</th><th>Currency</th><th>Super Admin ID</th><th>Margin</th><th>Advance</th></tr>'+d.history.map(x=>{let m={};try{m=JSON.parse(x.metadata_json||'{}')}catch{}return '<tr><td>'+esc(x.created_at)+'</td><td>'+esc(x.entity_id)+'</td><td>'+esc(m.super_admin_id||'—')+'</td><td>'+((Number(m.margin_bps||0)/100).toFixed(2))+'%</td><td>'+((m.client_advance_bps==null)?'—':(Number(m.client_advance_bps)/100).toFixed(2)+'%')+'</td></tr>'}).join('')+'</table>':'No pricing changes recorded.'}catch(e){msg(e.message)}}$('form').addEventListener('submit',async e=>{e.preventDefault();try{const currency=$('currency').value.trim().toUpperCase(),margin=Number($('margin').value),minimum=Number($('minimum').value),advance=$('advance').value===''?null:Number($('advance').value);if(!/^[A-Z]{3}$/.test(currency)||!Number.isFinite(margin)||margin<0||margin>100||!Number.isInteger(minimum)||minimum<0||(advance!==null&&(!Number.isFinite(advance)||advance<1||advance>100)))throw Error('Please enter valid currency and percentages.');const d=await api('POST',{currency,margin_bps:Math.round(margin*100),minimum_margin_minor:minimum,client_advance_bps:advance===null?null:Math.round(advance*100)});msg('Pricing policy saved for '+d.policy.currency,true);$('form').reset();$('minimum').value='0';await load()}catch(e){msg(e.message)}});load();</script></body></html>",{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}});}
